308	// ---------------------------------------------------------------------------
309	// Public API — Defaults Merge
310	// ---------------------------------------------------------------------------
311	
312	export interface ConflictEntry {
313	  defaultEntry: ModelEntry;
314	  localEntry: ModelEntry;
315	  reason: 'slug_collision';
316	}
317	
318	export interface LoadDefaultsResult {
319	  models: ModelEntry[];
320	  conflicts: ConflictEntry[];
321	}
322	
323	/**
324	 * Merges `default.json` into `local.json`.
325	 *
326	 * Merge rules:
327	 * - When a default entry's `id` already exists in `local.json`, the local entry
328	 *   wins (no overwrite).
329	 * - When a default entry's `id` is new but its `slug` collides with an existing
330	 *   local entry, the entry is not added and a conflict is recorded.
331	 * - All other default entries are appended to the local registry.
332	 *
333	 * Returns `{ models: ModelEntry[], conflicts: ConflictEntry[] }`.
334	 *
335	 * @throws {ApiError} if `default.json` cannot be read/parsed/validated.
336	 */
337	export async function loadDefaults(): Promise<LoadDefaultsResult> {
338	  // Read defaults
339	  let defaultParsed: unknown;
340	  try {
341	    defaultParsed = await readJsonFile(defaultJsonPath());
342	  } catch (err) {
343	    throw new ApiError(
344	      'READ_ERROR',
345	      `Failed to read default.json: ${(err as Error).message}`
346	    );
347	  }
348	
349	  const defaultValidation = ModelRegistrySchema.safeParse(defaultParsed);
350	  if (!defaultValidation.success) {
351	    throw new ApiError(
352	      'VALIDATION_ERROR',
353	      `default.json failed schema validation: ${defaultValidation.error.message}`
354	    );
355	  }
356	  const defaults = defaultValidation.data;
357	
358	  // Read local (may not exist yet — start from empty)
359	  let locals: ModelEntry[] = [];
360	  try {
361	    locals = await readModels();
362	  } catch (err) {
363	    // Note: ENOENT on local.json is handled inside readModels() via auto-init from
364	    // default.json — it never reaches here as READ_ERROR.  This catch handles the
365	    // narrow case where readModels() throws READ_ERROR for a non-ENOENT OS error
366	    // (e.g. permission denied) on local.json.  Treating that as "empty" is
367	    // intentional: loadDefaults() will then attempt to write the merged result, and
368	    // any ongoing permission issue will surface there as an atomicWriteJson error.
369	    // VALIDATION_ERROR and PARSE_ERROR (corrupt local.json) are deliberately re-thrown
370	    // so the caller learns the registry is in a bad state rather than silently
371	    // overwriting it with defaults.
372	    if (err instanceof ApiError && err.code === 'READ_ERROR') {
373	      locals = [];
374	    } else {
375	      throw err;
376	    }
377	  }
378	
379	  const localById = new Map(locals.map((m) => [m.id, m]));
380	  const localBySlug = new Map(locals.map((m) => [m.slug, m]));
381	
382	  const conflicts: ConflictEntry[] = [];
383	  const toAdd: ModelEntry[] = [];
384	
385	  for (const def of defaults) {
386	    if (localById.has(def.id)) {
387	      // Already present by ID — local wins, skip
388	      continue;
389	    }
390	    const slugConflict = localBySlug.get(def.slug);
391	    if (slugConflict !== undefined) {
392	      // Slug collision — record conflict, skip
393	      conflicts.push({ defaultEntry: def, localEntry: slugConflict, reason: 'slug_collision' });
394	      continue;
395	    }
396	    toAdd.push(def);
397	  }
398	
399	  if (toAdd.length === 0 && conflicts.length === 0) {
400	    return { models: locals, conflicts: [] };
401	  }
402	
403	  const merged = [...locals, ...toAdd];
404	
405	  if (toAdd.length > 0) {
406	    await atomicWriteJson(localJsonPath(), merged);
407	  }
408	
409	  return { models: merged, conflicts };
410	}
