416	/**
417	 * Checks whether `modelId` (UUID) is referenced in `assignments.json`.
418	 *
419	 * Returns `{ referenced: boolean, usages: string[] }` where `usages` lists the
420	 * persona IDs and/or `'default'` that reference this model UUID.
421	 */
422	export async function isModelReferenced(
423	  modelId: string
424	): Promise<{ referenced: boolean; usages: string[] }> {
425	  let assignments: ModelAssignments;
426	  try {
427	    assignments = await readAssignments();
428	  } catch {
429	    // If assignments.json doesn't exist or is unreadable, nothing references it
430	    return { referenced: false, usages: [] };
431	  }
432	
433	  const usages: string[] = [];
434	
435	  if (assignments.default_model_uuid === modelId) {
436	    usages.push('default');
437	  }
438	
439	  for (const [personaId, uuid] of Object.entries(assignments.persona_models)) {
440	    if (uuid === modelId) {
441	      usages.push(personaId);
442	    }
443	  }
444	
445	  return { referenced: usages.length > 0, usages };
446	}
